306	    <header>
307	        <div class="header-container">
308	            <h1>Welcome</h1>
309	            <button class="menu-toggle" aria-label="Toggle navigation menu" aria-controls="nav-menu" aria-expanded="false">☰</button>
310	            <nav aria-label="Primary navigation">
311	                <ul id="nav-menu">
312	                    <li><a href="#features">Features</a></li>
313	                    <li><a href="#get-started">Get Started</a></li>
314	                </ul>
315	            </nav>
316	        </div>
317	    </header>
318	
319	    <main id="main-content">
320	        <article>
321	            <h2>Modern Web Template</h2>
322	            <p>This is an improved HTML template built with best practices for performance, accessibility, and maintainability.</p>
323	        </article>
324	
325	        <article id="features">
326	            <h2>Key Features</h2>
327	            <p>
328	                This template includes semantic HTML elements, responsive design, modern CSS with gradients,
329	                proper meta tags for SEO, and accessibility considerations to create a solid foundation for any web project.
330	            </p>
331	            <ul class="feature-list">
332	                <li>Semantic HTML5 structure</li>
333	                <li>WCAG 2.1 accessibility compliance</li>
334	                <li>Mobile-first responsive design</li>
335	                <li>Keyboard navigation support</li>
336	                <li>Open Graph meta tags</li>
337	            </ul>
338	            <button type="button" class="cta-button" id="learn-more-btn" aria-label="Learn more and contact us">Learn More</button>
339	        </article>
340	
341	        <article id="get-started">
342	            <h2>Get Started</h2>
343	            <p>
344	                Use this template as a foundation for your next project. It's clean, well-structured, and ready to be
345	                customized to meet your specific needs.
346	            </p>
347	            <form id="contact-form" method="POST">
348	                <fieldset style="border: none; padding: 0; margin: 1.5rem 0;">
349	                    <legend style="font-weight: 600; margin-bottom: 1rem;">Get in Touch</legend>
350	                    <div style="margin-bottom: 1rem;">
351	                        <label for="name" style="display: block; margin-bottom: 0.5rem; font-weight: 500;">Name</label>
352	                        <input type="text" id="name" name="name" required style="width: 100%; max-width: 400px; padding: 0.75rem; border: 1px solid #ddd; border-radius: 4px; font-family: inherit;">
353	                    </div>
354	                    <div style="margin-bottom: 1rem;">
355	                        <label for="email" style="display: block; margin-bottom: 0.5rem; font-weight: 500;">Email</label>
356	                        <input type="email" id="email" name="email" required style="width: 100%; max-width: 400px; padding: 0.75rem; border: 1px solid #ddd; border-radius: 4px; font-family: inherit;">
357	                    </div>
358	                    <button type="submit" class="cta-button">Send Message</button>
359	                </fieldset>
360	            </form>
361	        </article>
362	    </main>
363	
364	    <footer>
365	        <p>&copy; 2026 Modern Web Template. All rights reserved.</p>
366	        <nav aria-label="Footer links">
367	            <ul>
368	                <li><a href="/privacy/">Privacy Policy</a></li>
369	                <li><a href="/terms/">Terms of Service</a></li>
370	            </ul>
371	        </nav>
372	    </footer>
373	
374	    <script type="application/ld+json">
375	    {
376	        "@context": "https://schema.org",
377	        "@type": "WebSite",
378	        "name": "Modern Web Template",
379	        "description": "A modern, accessible website built with best practices",
380	        "url": "https://example.com/",
381	        "author": {
382	            "@type": "Organization",
383	            "name": "Web Developer"
384	        },
385	        "mainEntity": {
386	            "@type": "CreativeWork",
387	            "name": "Modern Web Template",
388	            "description": "A semantic HTML5 template with accessibility and responsive design"
389	        }
390	    }
391	    </script>
392	
393	    <script>
394	        document.addEventListener('DOMContentLoaded', function() {
395	            const menuToggle = document.querySelector('.menu-toggle');
396	            const navMenu = document.getElementById('nav-menu');
397	
398	            if (menuToggle) {
399	                menuToggle.addEventListener('click', function() {
400	                    const isExpanded = menuToggle.getAttribute('aria-expanded') === 'true';
401	                    menuToggle.setAttribute('aria-expanded', !isExpanded);
402	                    navMenu.toggleAttribute('hidden');
403	                });
404	
405	                const navLinks = navMenu.querySelectorAll('a');
406	                navLinks.forEach(link => {
407	                    link.addEventListener('click', function() {
408	                        menuToggle.setAttribute('aria-expanded', 'false');
409	                        navMenu.setAttribute('hidden', '');
410	                    });
411	                });
412	            }
413	
414	            const learnMoreBtn = document.getElementById('learn-more-btn');
415	            if (learnMoreBtn) {
416	                learnMoreBtn.addEventListener('click', function() {
417	                    const getStartedSection = document.getElementById('get-started');
418	                    if (getStartedSection) {
419	                        getStartedSection.scrollIntoView({ behavior: 'smooth', block: 'start' });
420	                        getStartedSection.querySelector('#name').focus();
421	                    }
422	                });
423	            }
424	
425	            const contactForm = document.getElementById('contact-form');
426	            if (contactForm) {
427	                contactForm.addEventListener('submit', function(e) {
428	                    e.preventDefault();
429	                    alert('Thank you for your message! This is a demo form.');
430	                    contactForm.reset();
431	                });
432	            }
433	        });
434	    </script>
435	</body>
